-- Apply AFTER 003_public_email_signup.sql in the existing Supabase project's SQL Editor.
-- Additive: Auth, user_progress, owner binding and existing results remain unchanged.
-- No Realtime publication, Edge Functions, cron, or paid Supabase features required.
begin;

create table if not exists school_private.duel_questions (
  id text primary key,
  question jsonb not null check (jsonb_typeof(question) = 'object')
);
create table if not exists school_private.duel_rooms (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  host_id uuid not null references auth.users(id) on delete cascade,
  guest_id uuid references auth.users(id) on delete set null,
  host_name text not null,
  guest_name text,
  status text not null default 'waiting' check (status in ('waiting','active','completed','cancelled','expired')),
  questions jsonb not null check (jsonb_typeof(questions) = 'array' and jsonb_array_length(questions) = 5),
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null default (clock_timestamp() + interval '10 minutes'),
  started_at timestamptz,
  deadline timestamptz,
  finished_at timestamptz,
  result jsonb,
  check (guest_id is null or guest_id <> host_id)
);
create index if not exists duel_rooms_host_created on school_private.duel_rooms(host_id, created_at desc);
create index if not exists duel_rooms_guest_created on school_private.duel_rooms(guest_id, created_at desc);
create index if not exists duel_rooms_finished on school_private.duel_rooms(finished_at desc) where finished_at is not null;
create table if not exists school_private.duel_answers (
  room_id uuid not null references school_private.duel_rooms(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  question_id text not null,
  response jsonb not null,
  correct boolean not null,
  answered_at timestamptz not null default clock_timestamp(),
  primary key (room_id, user_id, question_id)
);
alter table school_private.duel_questions enable row level security;
alter table school_private.duel_rooms enable row level security;
alter table school_private.duel_answers enable row level security;
revoke all on school_private.duel_questions, school_private.duel_rooms, school_private.duel_answers from public, anon, authenticated;

create or replace function school_private.duel_identity()
returns uuid language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not school_private.has_access() then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  -- Polling must not rewrite student_profiles every three seconds.
  if not exists(select 1 from public.student_profiles where id = auth.uid()) then
    perform school_private.ensure_account_profile(auth.uid());
  end if;
  return auth.uid();
end;
$$;

-- Called only with the room row locked by an authenticated RPC. Persist final state once.
create or replace function school_private.duel_finish(p_room_id uuid, p_reason text, p_forfeit uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
declare r school_private.duel_rooms%rowtype; h int; g int; winner uuid;
begin
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if r.status <> 'active' then return; end if;
  select count(*) filter (where correct)::int into h from school_private.duel_answers where room_id = r.id and user_id = r.host_id;
  select count(*) filter (where correct)::int into g from school_private.duel_answers where room_id = r.id and user_id = r.guest_id;
  winner := case when p_forfeit = r.host_id then r.guest_id when p_forfeit = r.guest_id then r.host_id
    when h > g then r.host_id when g > h then r.guest_id else null end;
  update school_private.duel_rooms set status = 'completed', finished_at = clock_timestamp(),
    result = jsonb_build_object('winner_id', winner, 'reason', p_reason, 'scores', jsonb_build_array(
      jsonb_build_object('id', r.host_id, 'name', r.host_name, 'score', h),
      jsonb_build_object('id', r.guest_id, 'name', r.guest_name, 'score', g))) where id = r.id;
end;
$$;

create or replace function school_private.duel_settle(p_room_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare r school_private.duel_rooms%rowtype;
begin
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if r.status = 'waiting' and r.expires_at <= clock_timestamp() then
    update school_private.duel_rooms set status = 'expired', finished_at = clock_timestamp() where id = r.id;
  elsif r.status = 'active' and r.deadline <= clock_timestamp() then
    perform school_private.duel_finish(r.id, 'timeout');
  end if;
end;
$$;

create or replace function school_private.duel_snapshot(p_room_id uuid, p_uid uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare r school_private.duel_rooms%rowtype; h int; g int; hs int; gs int; own_count int; q jsonb; players jsonb; me jsonb;
begin
  select * into r from school_private.duel_rooms where id = p_room_id;
  if not found or p_uid not in (r.host_id, coalesce(r.guest_id, r.host_id)) then
    raise exception 'room_not_found' using errcode = '42501';
  end if;
  select count(*)::int, count(*) filter(where correct)::int into h, hs from school_private.duel_answers where room_id = r.id and user_id = r.host_id;
  select count(*)::int, count(*) filter(where correct)::int into g, gs from school_private.duel_answers where room_id = r.id and user_id = r.guest_id;
  own_count := case when p_uid = r.host_id then h else g end;
  players := jsonb_build_array(jsonb_build_object('id',r.host_id,'name',r.host_name,'answered',h,'score',case when r.status = 'completed' then hs else null end,'finished',h = 5));
  if r.guest_id is not null then players := players || jsonb_build_array(jsonb_build_object('id',r.guest_id,'name',r.guest_name,'answered',g,'score',case when r.status = 'completed' then gs else null end,'finished',g = 5)); end if;
  select value into me from jsonb_array_elements(players) where value ->> 'id' = p_uid::text;
  if r.status = 'active' and own_count < 5 then
    q := r.questions -> own_count;
    -- Never return the answer key or explanation during the duel.
    q := jsonb_build_object('id',q -> 'id','prompt',q -> 'prompt','options',q -> 'options');
  end if;
  return jsonb_build_object('id',r.id,'code',r.code,'status',r.status,'host_id',r.host_id,'guest_id',r.guest_id,
    'created_at',r.created_at,'expires_at',r.expires_at,'started_at',r.started_at,'deadline',r.deadline,
    'finished_at',r.finished_at,'server_now',clock_timestamp(),'question_count',5,'players',players,'me',me,'question',q,'result',r.result);
end;
$$;

create or replace function public.duel_create()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r uuid; qs jsonb; code text; display text;
begin
  u := school_private.duel_identity();
  perform pg_advisory_xact_lock(hashtextextended(u::text, 744));
  for r in select id from school_private.duel_rooms where (host_id = u or guest_id = u) and status in ('waiting','active') order by created_at loop
    perform school_private.duel_settle(r);
  end loop;
  select id into r from school_private.duel_rooms where (host_id = u or guest_id = u) and status in ('waiting','active') order by created_at desc limit 1;
  if r is not null then return school_private.duel_snapshot(r,u); end if;
  if (select count(*) from school_private.duel_rooms where host_id = u and created_at > clock_timestamp() - interval '1 hour') >= 20 then
    raise exception 'room_rate_limit' using errcode = '22023';
  end if;
  select jsonb_agg(question) into qs from (select question from school_private.duel_questions order by random() limit 5) selected;
  if coalesce(jsonb_array_length(qs),0) <> 5 then raise exception 'duel_bank_not_ready' using errcode = '55000'; end if;
  select display_name into display from public.student_profiles where id = u;
  loop
    code := upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
    begin
      insert into school_private.duel_rooms(code,host_id,host_name,questions) values(code,u,coalesce(display,'لاعب'),qs) returning id into r;
      exit;
    exception when unique_violation then null;
    end;
  end loop;
  return school_private.duel_snapshot(r,u);
end;
$$;

create or replace function public.duel_join(p_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r school_private.duel_rooms%rowtype; other uuid; display text;
begin
  u := school_private.duel_identity();
  perform pg_advisory_xact_lock(hashtextextended(u::text,744));
  if p_code is null or upper(btrim(p_code)) !~ '^[A-F0-9]{10}$' then raise exception 'invalid_room_code' using errcode = '22023'; end if;
  select * into r from school_private.duel_rooms where code = upper(btrim(p_code)) for update;
  if not found then raise exception 'room_not_found' using errcode = '22023'; end if;
  if r.host_id = u then raise exception 'cannot_join_own_room' using errcode = '22023'; end if;
  if r.guest_id = u then perform school_private.duel_settle(r.id); return school_private.duel_snapshot(r.id,u); end if;
  perform school_private.duel_settle(r.id);
  select * into r from school_private.duel_rooms where id = r.id;
  if r.status <> 'waiting' or r.guest_id is not null then raise exception 'room_unavailable' using errcode = '22023'; end if;
  for other in select id from school_private.duel_rooms where (host_id = u or guest_id = u) and status in ('waiting','active') loop
    perform school_private.duel_settle(other);
  end loop;
  if exists(select 1 from school_private.duel_rooms where (host_id = u or guest_id = u) and status in ('waiting','active')) then raise exception 'already_in_room' using errcode = '22023'; end if;
  select display_name into display from public.student_profiles where id = u;
  update school_private.duel_rooms set guest_id = u, guest_name = coalesce(display,'لاعب'), status = 'active',
    started_at = clock_timestamp(), deadline = clock_timestamp() + interval '90 seconds' where id = r.id;
  return school_private.duel_snapshot(r.id,u);
end;
$$;

create or replace function public.duel_state(p_room_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r school_private.duel_rooms%rowtype;
begin
  u := school_private.duel_identity();
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if not found or u not in(r.host_id,coalesce(r.guest_id,r.host_id)) then raise exception 'room_not_found' using errcode = '42501'; end if;
  perform school_private.duel_settle(r.id);
  return school_private.duel_snapshot(r.id,u);
end;
$$;

create or replace function public.duel_answer(p_room_id uuid, p_question_id text, p_answer jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r school_private.duel_rooms%rowtype; count_own int; q jsonb; old jsonb;
begin
  u := school_private.duel_identity();
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if not found or u not in(r.host_id,coalesce(r.guest_id,r.host_id)) then raise exception 'room_not_found' using errcode = '42501'; end if;
  perform school_private.duel_settle(r.id);
  select * into r from school_private.duel_rooms where id = p_room_id;
  -- A network retry of exactly the same submitted answer is idempotent.
  select response into old from school_private.duel_answers where room_id = r.id and user_id = u and question_id = p_question_id;
  if found then
    if old is distinct from p_answer then raise exception 'answer_already_submitted' using errcode = '22023'; end if;
    return school_private.duel_snapshot(r.id,u);
  end if;
  if r.status <> 'active' then return school_private.duel_snapshot(r.id,u); end if;
  select count(*)::int into count_own from school_private.duel_answers where room_id = r.id and user_id = u;
  q := r.questions -> count_own;
  if q is null or p_question_id is distinct from q ->> 'id' then raise exception 'question_out_of_order' using errcode = '22023'; end if;
  if p_answer is null or jsonb_typeof(p_answer) <> 'string' or not exists(select 1 from jsonb_array_elements(q -> 'options') x where x -> 'id' = p_answer) then
    raise exception 'invalid_answer' using errcode = '22023';
  end if;
  insert into school_private.duel_answers(room_id,user_id,question_id,response,correct) values(r.id,u,p_question_id,p_answer,p_answer = q -> 'correct_answer');
  if (select count(*) from school_private.duel_answers where room_id = r.id) = 10 then perform school_private.duel_finish(r.id,'answered'); end if;
  return school_private.duel_snapshot(r.id,u);
end;
$$;

create or replace function public.duel_leave(p_room_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r school_private.duel_rooms%rowtype;
begin
  u := school_private.duel_identity();
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if not found or u not in(r.host_id,coalesce(r.guest_id,r.host_id)) then raise exception 'room_not_found' using errcode = '42501'; end if;
  perform school_private.duel_settle(r.id);
  select * into r from school_private.duel_rooms where id = p_room_id;
  if r.status = 'waiting' then update school_private.duel_rooms set status='cancelled',finished_at=clock_timestamp() where id = r.id;
  elsif r.status = 'active' then perform school_private.duel_finish(r.id,'forfeit',u); end if;
  return school_private.duel_snapshot(r.id,u);
end;
$$;

create or replace function public.duel_recent()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; room_id uuid; result jsonb := '[]';
begin
  u := school_private.duel_identity();
  for room_id in select id from school_private.duel_rooms where host_id = u or guest_id = u order by created_at desc limit 20 loop
    perform school_private.duel_settle(room_id);
    result := result || jsonb_build_array(school_private.duel_snapshot(room_id,u));
  end loop;
  return result;
end;
$$;

create or replace function public.platform_admin_duels(p_limit int default 20, p_offset int default 0)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare room_id uuid; result jsonb; total bigint;
begin
  if not school_private.is_admin() then raise exception 'administrator_required' using errcode = '42501'; end if;
  if p_limit is null or p_offset is null or p_limit < 1 or p_limit > 100 or p_offset < 0 then raise exception 'invalid_pagination' using errcode = '22023'; end if;
  -- Settle stale rooms on the requested page; no background daemon is needed.
  for room_id in select id from school_private.duel_rooms order by created_at desc, id limit p_limit offset p_offset loop
    perform school_private.duel_settle(room_id);
  end loop;
  select count(*) into total from school_private.duel_rooms;
  select coalesce(jsonb_agg(row_data),'[]') into result from (
    select jsonb_build_object('id',r.id,'code',r.code,'status',r.status,'created_at',r.created_at,'started_at',r.started_at,'finished_at',r.finished_at,
      'host_id',r.host_id,'host_name',r.host_name,'host_email',h.email,'guest_id',r.guest_id,'guest_name',r.guest_name,'guest_email',g.email,'result',r.result) row_data
    from school_private.duel_rooms r left join auth.users h on h.id = r.host_id left join auth.users g on g.id = r.guest_id
    order by r.created_at desc, r.id limit p_limit offset p_offset
  ) page;
  return jsonb_build_object('rooms',result,'total',total,'limit',p_limit,'offset',p_offset);
end;
$$;

revoke all on function school_private.duel_identity(), school_private.duel_finish(uuid,text,uuid), school_private.duel_settle(uuid), school_private.duel_snapshot(uuid,uuid) from public, anon, authenticated;
revoke all on function public.duel_create(), public.duel_join(text), public.duel_state(uuid), public.duel_answer(uuid,text,jsonb), public.duel_leave(uuid), public.duel_recent(), public.platform_admin_duels(int,int) from public, anon, authenticated;
grant execute on function public.duel_create(), public.duel_join(text), public.duel_state(uuid), public.duel_answer(uuid,text,jsonb), public.duel_leave(uuid), public.duel_recent(), public.platform_admin_duels(int,int) to authenticated;

