er":"o2","explanation":"ورد أن القرآن أعظم معجزاته وأهمها."},{"id":"u01_l03_q003","prompt":"أي مقارنة بين المعجزة المادية والقرآن تطابق الدرس؟","options":[{"id":"o3","text":"القرآن معجزة مادية مؤقتة فقط"},{"id":"o1","text":"المادية مؤقتة خاصة بقوم، والقرآن معجزة عقلية خالدة للناس كافة"},{"id":"o4","text":"كلتاهما مؤقتة خاصة بقوم واحد"},{"id":"o2","text":"المادية خالدة والقرآن مؤقت"}],"correct_answer":"o1","explanation":"قسم الكتاب المعجزات إلى مادية مؤقتة وعقلية خالدة تتمثل في القرآن."},{"id":"u01_l03_q027","prompt":"ما التصنيف الأدق لمثالين: دقة لفظ الاستئناس، وحفظ الدماء بتشريع القصاص؟","options":[{"id":"o2","text":"كلاهما غيبي"},{"id":"o1","text":"الأول بياني والثاني تشريعي"},{"id":"o3","text":"الأول غيبي والثاني علمي"},{"id":"o4","text":"كلاهما علمي"}],"correct_answer":"o1","explanation":"الأول يتعلق باتساع دلالة اللفظ، والثاني بأثر التشريع في تنظيم الحياة وحفظ الدماء."},{"id":"u01_l04_q001","prompt":"ما الأثر الذي يذكره الدرس للنصيحة في المجتمع؟","options":[{"id":"o1","text":"إصلاح سلوك الفرد دون امتداد أثره إلى المجتمع"},{"id":"o2","text":"حصر مسؤولية الإصلاح في فئة دون سائر الأفراد"},{"id":"o4","text":"نشر القيم الفاضلة وتنقية المجتمع من المفاسد"},{"id":"o3","text":"تقوية الروابط الاجتماعية دون العناية بتغيير المنكر"}],"correct_answer":"o4","explanation":"ربط التعلم القبلي النصيحة بنشر القيم وتنقية المجتمع من المفاسد والمضار."},{"id":"u01_l04_q003","prompt":"ما المقصود بالأمر بالمعروف والنهي عن المنكر؟","options":[{"id":"o4","text":"حصر النصيحة في الأقارب"},{"id":"o1","text":"دعوة الناس إلى الخير والفضيلة ونهيهم عن الشر والرذيلة"},{"id":"o2","text":"إجبار الجميع بلا ضوابط"},{"id":"o3","text":"مراقبة خصوصيات الناس كلها"}],"correct_answer":"o1","explanation":"هذا تعريف الدرس، مع بيان أثره في حفظ المجتمع والدولة."},{"id":"u01_l04_q002","prompt":"كيف يكون الفرد إيجابيا في التناصح بحسب الدرس؟","options":[{"id":"o3","text":"يجعلها وسيلة للإحراج فقط"},{"id":"o1","text":"يتجنب الخير كله"},{"id":"o2","text":"يقدمها ويرفضها لنفسه دائما"},{"id":"o4","text":"يقدم النصيحة لغيره ويقبلها منه"}],"correct_answer":"o4","explanation":"ذكر الكتاب تقديم النصيحة للغير وقبولها منه معا."},{"id":"u01_l04_q027","prompt":"طالب يريد ممارسة سلطة العقاب على غيره بحجة أن الأمر بالمعروف واجب على الجميع؛ ما التصحيح؟","options":[{"id":"o1","text":"واجب النصح يقتضي إعطاء الفرد صلاحيات العقاب كلها"},{"id":"o2","text":"الإنكار يراعى فيه العلم والقدرة والتغيير باليد لأهل السلطة"},{"id":"o3","text":"الإنكار لا يحتاج إلى معرفة الفعل أو تقدير عاقبته"},{"id":"o4","text":"كل من رأى المنكر يجوز له استعمال أي وسيلة شاء"}],"correct_answer":"o2","explanation":"يجمع الدرس عموم المسؤولية مع حدودها وتخصيص التغيير باليد لأصحاب السلطة."},{"id":"u01_l05_q001","prompt":"من يعلم وقت اليوم الآخر وفق الدرس؟","options":[{"id":"o1","text":"الله تعالى وحده"},{"id":"o4","text":"العلماء باستنباط الموعد من علامات الساعة"},{"id":"o2","text":"الأنبياء بما أطلعهم الله عليه من علامات الساعة"},{"id":"o3","text":"الملائكة الموكلون بأحداث اليوم الآخر"}],"correct_answer":"o1","explanation":"ذكر الكتاب أن الله استأثر بعلم وقته ولم يطلع عليه أحدا من خلقه."},{"id":"u01_l05_q004","prompt":"ما المقصود بالإيمان باليوم الآخر؟","options":[{"id":"o4","text":"الجزم بموعد الساعة"},{"id":"o1","text":"معرفة أسماء السور فقط"},{"id":"o2","text":"الاعتقاد الجازم بأن الله يبعث الناس للحساب والجزاء"},{"id":"o3","text":"اعتقاد انتهاء كل شيء بالموت دون بعث"}],"correct_answer":"o2","explanation":"يعرف الدرس الإيمان باليوم الآخر بالبعث للحساب والجزاء."},{"id":"u01_l05_q002","prompt":"ما الحكمة من العلامات التي تسبق اليوم الآخر؟","options":[{"id":"o1","text":"تنبيه الناس للتوبة والاستعداد بالأعمال الصالحة"},{"id":"o4","text":"حصر العلم بالساعة في البشر"},{"id":"o2","text":"إسقاط الاستعداد"},{"id":"o3","text":"إعطاء كل إنسان تاريخا محددا"}],"correct_answer":"o1","explanation":"ربط الدرس العلامات بالتنبه والرجوع إلى الله والتوبة والاستعداد للقائه."},{"id":"u01_l05_q034","prompt":"كيف يعين الإيمان باليوم الآخر على مواجهة الابتلاءات بحسب الدرس؟","options":[{"id":"o4","text":"يجعل الصبر غير مطلوب"},{"id":"o1","text":"يعطي الإنسان علم الغيب"},{"id":"o3","text":"يمنع وقوع جميع المصائب في الدنيا"},{"id":"o2","text":"يولد الطمأنينة والرضا والصبر لليقين بالتعويض خيرا في الآخرة"}],"correct_answer":"o2","explanation":"يشرح الأثر الرابع هذا الربط بين اليقين بالآخرة والطمأنينة والصبر."},{"id":"u01_l06_q002","prompt":"بماذا تتعلق الأحكام الشرعية العملية في تعريف الدرس؟","options":[{"id":"o3","text":"أرقام الصفحات"},{"id":"o4","text":"أقوال الإنسان وأفعاله"},{"id":"o2","text":"أطوار النبات فقط"},{"id":"o1","text":"أسماء النجوم فقط"}],"correct_answer":"o4","explanation":"يعرفها صندوق أتوقف بأنها أحكام تتعلق بما يصدر عن الإنسان من أقوال وأفعال."},{"id":"u01_l06_q005","prompt":"على من أوجب الدرس الاجتهاد في كل عصر؟","options":[{"id":"o1","text":"علماء المسلمين"},{"id":"o3","text":"كل فرد مهما كان علمه"},{"id":"o2","text":"غير المختصين وحدهم"},{"id":"o4","text":"المسافر وحده"}],"correct_answer":"o1","explanation":"نص الكتاب على أن الاجتهاد واجب على علماء المسلمين في كل عصر."},{"id":"u01_l06_q004","prompt":"أي تعريف يطابق الاجتهاد في الدرس؟","options":[{"id":"o2","text":"بذل العالم وسعه في تغيير نصوص الأحكام القطعية بالاجتهاد"},{"id":"o1","text":"بذل غير المختص وسعه في تطبيق كل حكم ثابت بلا استثناء"},{"id":"o3","text":"بذل العالم وسعه لاستنباط حكم عملي ليس فيه نص قطعي مباشر"},{"id":"o4","text":"بذل العالم وسعه في صياغة أحكام تخالف الأصول الثابتة"}],"correct_answer":"o3","explanation":"تعريف الكتاب يقيد الاجتهاد بالعالم وبالأحكام العملية التي لم يرد نص قطعي يبين حكمها مباشرة."},{"id":"u01_l06_q036","prompt":"شخص يقترح تقليل عدد الصلوات المفروضة بحجة مواكبة العصر؛ ما تقويم قوله وفق الدرس؟","options":[{"id":"o4","text":"يجوز تبديل عدد الصلوات إذا تغيرت ظروف الناس"},{"id":"o3","text":"لا يجوز تغيير الحكم القطعي بالاجتهاد لمجرد مواكبة العصر"},{"id":"o2","text":"كل قرار حديث يفتح إعادة الاجتهاد في الفرائض"},{"id":"o1","text":"التغيير مقبول إذا اتفق عليه عدد كبير من الناس"}],"correct_answer":"o3","explanation":"يميز الدرس بين المستجدات التي تحتاج استنباطا والمسائل القطعية التي لا يجتهد في تغييرها."},{"id":"u02_l01_q001","prompt":"أي وصف يجمع تصنيف سورة الأعراف وعدد آياتها وفق الدرس؟","options":[{"id":"o3","text":"مكية وعدد آياتها 286"},{"id":"o2","text":"مدنية وعدد آياتها 206"},{"id":"o4","text":"مدنية وعدد آياتها 286"},{"id":"o1","text":"مكية وعدد آياتها 206"}],"correct_answer":"o1","explanation":"يذكر صندوق التعريف في الصفحة 48 أن سورة الأعراف مكية وعدد آياتها 206 آيات."},{"id":"u02_l01_q003","prompt":"لماذا سميت السورة بالأعراف؟","options":[{"id":"o4","text":"لذكر تقسيم الغنائم فيها"},{"id":"o3","text":"لذكر يوم تبوك فيها"},{"id":"o2","text":"لذكر حال أهل الأعراف فيها"},{"id":"o1","text":"لذكر قصة البقرة فيها"}],"correct_answer":"o2","explanation":"نص التعريف على أن التسمية بسبب ذكر حال أهل الأعراف."},{"id":"u02_l01_q004","prompt":"أي وصف لأهل الأعراف ومآلهم يوافق التعريف الوارد في الكتاب؟","options":[{"id":"o2","text":"رجحت سيئاتهم ولا يذكر الكتاب لهم مآلا"},{"id":"o3","text":"تساوت أعمالهم ويبقون في الدنيا"},{"id":"o4","text":"تساوت حسناتهم وسيئاتهم ويكون مآلهم إلى الجنة"},{"id":"o1","text":"ليس لهم حسنات ولا سيئات ومآلهم إلى الدنيا"}],"correct_answer":"o4","explanation":"يذكر الكتاب وجودهم في مكان بين الجنة والنار مع تساوي الحسنات والسيئات، ثم مآلهم إلى الجنة."},{"id":"u02_l01_q030","prompt":"أي قرار يحقق الأمر بالزينة والنهي عن الإسراف معا؟","options":[{"id":"o3","text":"ترك الستر بحجة الاقتصاد"},{"id":"o1","text":"اختيار لباس ساتر مناسب مع إنفاق معتدل"},{"id":"o2","text":"الإنفاق بلا حد لأن الزينة مباحة"},{"id":"o4","text":"تحريم كل لباس جميل على الناس"}],"correct_answer":"o1","explanation":"الجمع بين النصين يقتضي الستر والزينة مع الاعتدال، لا إلغاء أحد التوجيهين."},{"id":"u02_l02_q001","prompt":"ما تعريف المصلحة في الدرس؟","options":[{"id":"o1","text":"منفعة تحصل بجلب النفع أو دفع الضرر"},{"id":"o3","text":"العادة التي تتكرر بين الناس في تعاملهم"},{"id":"o4","text":"الاجتهاد الذي يبذله الفقيه لاستنباط الحكم"},{"id":"o2","text":"الرخصة التي تخفف الحكم عند تحقق العذر"}],"correct_answer":"o1","explanation":"عرف الكتاب المصلحة بجلب النفع للناس أو دفع الضرر