":"وحي يقتصر على المعاني التي وضعها الرواة من أنفسهم"},{"id":"o1","text":"وحي من الله باللفظ والمعنى كما في القرآن الكريم"},{"id":"o2","text":"وحي من الله باللفظ دون المعنى"},{"id":"o3","text":"وحي من الله بالمعنى دون اللفظ"}],"correct_answer":"o3","explanation":"هذا هو الوصف الوارد في بيان مكانة السنة."},{"id":"u02_l03_q027","prompt":"يريد باحث أحاديث صحابي معين مهما اختلفت موضوعاتها؛ أي تنظيم يلائم غرضه مباشرة ولماذا؟","options":[{"id":"o1","text":"المسانيد لأنها تجمع المرويات بحسب أسماء الصحابة"},{"id":"o4","text":"الشروح لأنها لا ترتبط بكتب الحديث"},{"id":"o2","text":"الصحاح لأن عنوانها يعني أسماء الصحابة"},{"id":"o3","text":"الأبواب الفقهية لأنها تجمع كل راو تحت اسمه"}],"correct_answer":"o1","explanation":"الاختيار مبني على معيار ترتيب المسانيد، لا على درجة الحديث وحدها."},{"id":"u02_l04_q001","prompt":"على أي منهج وصف الدرس قيام الأمة الوسط؟","options":[{"id":"o2","text":"التدرج بتأخير أداء الواجبات حتى تزول المصاعب"},{"id":"o1","text":"التيسير بإسقاط التكليف عند وجود المشقة المعتادة"},{"id":"o3","text":"الاحتياط باجتناب كل مباح يحتمل حصول ضرر"},{"id":"o4","text":"التوازن والاعتدال"}],"correct_answer":"o4","explanation":"يقرر التعلم القبلي أن الأمة الوسط تقوم على التوازن والاعتدال."},{"id":"u02_l04_q004","prompt":"ما العدد الذي يدل عليه «الرهط» في شرح المفردات؟","options":[{"id":"o3","text":"واحد فقط"},{"id":"o1","text":"أكثر من مئة"},{"id":"o2","text":"اثنان فقط"},{"id":"o4","text":"من ثلاثة إلى عشرة"}],"correct_answer":"o4","explanation":"فسر الكتاب الرهط بأنه من ثلاثة إلى عشرة."},{"id":"u02_l04_q009","prompt":"ما العامل الذي يربطه الدرس بكثرة علم أنس وروايته؟","options":[{"id":"o3","text":"تأليفه كتابًا في الفقه قبل بلوغ سن الرشد"},{"id":"o2","text":"ملازمته النبي ﷺ وتلقي العلم عنه سنوات"},{"id":"o1","text":"انتسابه إلى علم الكلام أكثر من رواية الحديث"},{"id":"o4","text":"انقطاعه عن المدينة وابتعاده عن الصحابة"}],"correct_answer":"o2","explanation":"يربط النص كثرة الرواية بتربيته وملازمته للنبي وتلقي العلم عنه."},{"id":"u02_l04_q028","prompt":"طالب يتدرب على المحافظة على الصلاة المفروضة ويصف ذلك بالتشدد؛ أي تمييز يصحح حكمه؟","options":[{"id":"o1","text":"المحافظة على الفريضة غلو يمنع تعلّم العلوم"},{"id":"o3","text":"التدرب على أداء الفريضة مجاهدة محمودة لا تشدد مذموم"},{"id":"o4","text":"المجاهدة المشروعة تقتضي زيادة تكاليف غير واردة"},{"id":"o2","text":"كل التزام عبادي مستمر يعد خروجا عن السنة"}],"correct_answer":"o3","explanation":"يجمع التصحيح بين تعريف المجاهدة والتشدد في الدرس."},{"id":"u02_l05_q001","prompt":"لمن بعث النبي محمد ﷺ بحسب التعلم القبلي؟","options":[{"id":"o3","text":"للقبائل المحيطة بالمدينة وحدها"},{"id":"o1","text":"للناس كافة"},{"id":"o4","text":"لأهل مكة وحدهم"},{"id":"o2","text":"لملوك الجزيرة وحدهم"}],"correct_answer":"o1","explanation":"يقارن الدرس بعثته العامة ببعثة كل نبي إلى قومه خاصة."},{"id":"u02_l05_q004","prompt":"من أي مادة صنع الخاتم الذي اتخذه النبي ﷺ لختم خطاباته؟","options":[{"id":"o3","text":"الذهب"},{"id":"o1","text":"الحديد"},{"id":"o2","text":"الفضة"},{"id":"o4","text":"النحاس"}],"correct_answer":"o2","explanation":"نص صندوق أتوقف على خاتم من فضة."},{"id":"u02_l05_q002","prompt":"ما الحدث الذي أتاح التفرغ لدعوة الملوك داخل الجزيرة وخارجها في سياق الدرس؟","options":[{"id":"o1","text":"صلح الحديبية"},{"id":"o3","text":"يوم تبوك"},{"id":"o2","text":"يوم مؤتة"},{"id":"o4","text":"وفاة النجاشي"}],"correct_answer":"o1","explanation":"ذكر النص صلح الحديبية نقطة تحول أتاحت التفرغ للدعوة."},{"id":"u02_l05_q031","prompt":"ما التفسير الجامع لاختلاف استعمال ألقاب المخاطبين داخل الجزيرة وخارجها كما عرضه الكتاب؟","options":[{"id":"o1","text":"مراعاة واقع السيادة والمنصب وأحوال المخاطبين في كل مجموعة"},{"id":"o4","text":"التناقض في هدف الرسائل"},{"id":"o2","text":"جهل النبي بأسماء الملوك الخارجيين"},{"id":"o3","text":"أن جميع الملوك داخل الجزيرة مستقلون بخلاف الخارج"}],"correct_answer":"o1","explanation":"علل الدرس ترك ألقاب كثير من الداخليين بفقد السيادة، وذكر مراعاة مناصب الخارجيين وألقابهم."},{"id":"u02_l06_q001","prompt":"أي معركة وصفها التعلم القبلي بأنها أول لقاء بين المسلمين والروم؟","options":[{"id":"o4","text":"مؤتة"},{"id":"o1","text":"الحديبية"},{"id":"o3","text":"تبوك"},{"id":"o2","text":"بدر"}],"correct_answer":"o4","explanation":"افتتح الدرس بسياق معركة مؤتة ووصفها بأول لقاء."},{"id":"u02_l06_q010","prompt":"من الصحابي الذي أبرز الدرس كثرة إنفاقه على تجهيز الجيش؟","options":[{"id":"o4","text":"دحية الكلبي"},{"id":"o2","text":"عثمان بن عفان"},{"id":"o3","text":"عقبة بن عامر"},{"id":"o1","text":"الحارث بن عمير"}],"correct_answer":"o2","explanation":"ذكر النص عثمان من أكثر المنفقين وأورد الثناء عليه."},{"id":"u02_l06_q002","prompt":"ما أثر خطة خالد بن الوليد في معركة مؤتة كما يورده التعلم القبلي؟","options":[{"id":"o4","text":"المحافظة على جيش المسلمين"},{"id":"o1","text":"منع إرسال كل الرسائل"},{"id":"o2","text":"إلغاء جميع المعاهدات"},{"id":"o3","text":"بدء تدوين الحديث"}],"correct_answer":"o4","explanation":"ذكر النص وضعه خطة محكمة أفضت إلى المحافظة على الجيش."},{"id":"u02_l06_q031","prompt":"لماذا اعتبرت تبوك نصرا في الدرس رغم عدم وقوع قتال؟","options":[{"id":"o2","text":"لأن كل نصر يشترط معركة بالسلاح"},{"id":"o4","text":"لأن الجيش أخذ أسرى كثيرين كما يقول النص"},{"id":"o1","text":"لأن المسلمين لم يواجهوا مشقة"},{"id":"o3","text":"لانسحاب العدو وظهور قوة الردع وعقد الصلح"}],"correct_answer":"o3","explanation":"يجمع الدرس الانسحاب وإظهار القوة والمعاهدات في نتائج الخروج، ولا يذكر معركة فعلية."},{"id":"u02_l07_q002","prompt":"أي مجموعة يوردها الدرس ضمن الحقوق الاجتماعية للمرأة؟","options":[{"id":"o2","text":"منع التعلم واختيار الزوج"},{"id":"o4","text":"التكريم والتعلم واختيار الزوج والمشاركة في بناء الأسرة"},{"id":"o1","text":"المنع من المشاركة في تربية الأبناء"},{"id":"o3","text":"حصر الحقوق في المال وحده"}],"correct_answer":"o4","explanation":"هذه أمثلة الجوانب الاجتماعية في التعلم القبلي."},{"id":"u02_l07_q003","prompt":"ما المقصود بالحقوق السياسية في تعريف الدرس؟","options":[{"id":"o2","text":"امتيازات تخص التعليم والعلاج دون غيرهما"},{"id":"o4","text":"امتيازات تقتصر على التصرفات العائلية الفردية"},{"id":"o3","text":"امتيازات تُشرك